referenceSolutions.javascript:
function squareGaugesProofStrip(readings, k) {
  const a=readings; let out=[];
  for(const x of a){let l=0,r=x+1;while(l+1<r){const m=Math.floor((l+r)/2);if(m*m<=x)l=m;else r=m;}out.push(l);}
  return out;
}

